import{_ as r,o,c as t,ae as a}from"./chunks/framework.Dn6zxbF8.js";const h=JSON.parse('{"title":"Logging Level and Error Reporting Usage","description":"","frontmatter":{"id":"7565730517","title":"Logging Level and Error Reporting Usage","state":"Approved","created":"2025-03-31T00:00:00.000Z","tags":["error-reporting","logging","sentry","observability"],"category":"Platform"},"headers":[],"relativePath":"adrs/7565730517/README.md","filePath":"adrs/7565730517/README.md"}'),i={name:"adrs/7565730517/README.md"};function l(n,e,s,d,c,g){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="logging-level-and-error-reporting-usage" tabindex="-1">Logging Level and Error Reporting Usage <a class="header-anchor" href="#logging-level-and-error-reporting-usage" aria-label="Permalink to &quot;Logging Level and Error Reporting Usage&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Currently, the volume and quality of logs—particularly Sentry errors—are reducing the effectiveness of the tool for debugging and operations. Much of the logging noise stems from messages that do not require action, creating false alarms and distracting from actionable issues.</p><h3 id="error-reporting" tabindex="-1">Error Reporting <a class="header-anchor" href="#error-reporting" aria-label="Permalink to &quot;Error Reporting&quot;">​</a></h3><p>Error Reporting tools (e.g., Sentry, Datadog Error, etc.) should be a high-signal tool. All logs sent to the error reporting tool must be actionable.</p><ul><li>Do not log messages to the error reporting tool unless they require immediate investigation or fixing. Use the regular logger module for informational or ignorable issues.</li><li>If an error issue is raised: <ul><li>Immediately assign it to yourself.</li><li>Fix it promptly. If unsure how to proceed, ask for help immediately.</li></ul></li><li>The long-term goal is to have a silent Error Reporting tool.</li></ul><h3 id="logger" tabindex="-1">Logger <a class="header-anchor" href="#logger" aria-label="Permalink to &quot;Logger&quot;">​</a></h3><p>Use the logger module for all standard logging purposes.</p><ul><li><code>error</code> logs are treated as <code>500</code> errors and must be addressed. <ul><li>Prefer <code>error</code> over <code>critical</code>, <code>alert</code>, or <code>emergency</code> unless there is a strong justification, in which case document the reasoning clearly.</li></ul></li><li><code>critical</code>, <code>alert</code>, and <code>emergency</code> should be reserved for extreme situations, such as data corruption or unrecoverable system failures.</li><li><code>warning</code> logs are treated like <code>400</code> errors. <ul><li>They signal that attention might be needed, but action is not always required.</li><li>If a warning proves meaningless or too frequent, it should either be removed, lowered, or replaced with metrics.</li></ul></li><li>Info/debug logs are always acceptable for internal understanding and observability.</li></ul><p>Any log with the <code>error</code> <code>critical</code> <code>alert</code> or <code>emergency</code> must be acted upon. Ideally, we should not have any of those logs. Treat them as an <code>500</code> error. Being said, use <code>error</code> level instead of <code>critical</code> <code>alert</code> or <code>emergency</code> unless there is a strong reason not to; please document it in that case.</p><p>Use <code>warning</code> to call the attention, but it may or may not require action. Ideally, we move the warning to a lower or higher level or add metrics instead. Treat <code>warning</code> the log level as an <code>400</code> error.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <code>MUST NOT</code> log to the error reporting tool unless the issue is actionable and needs fixing.</li><li>You <code>MUST</code> treat <code>error</code> logs as production issues to be fixed. You <code>SHOULD</code> validate log level usage as part of code reviews. PRs introducing <code>error</code> or higher logs must justify them.</li><li>You <code>SHOULD</code> avoid using <code>critical</code>, <code>alert</code>, or <code>emergency</code> unless strictly necessary.</li><li>You <code>SHOULD</code> avoid noise from <code>warning</code> logs; triage them regularly.</li><li>You <code>MUST</code> ensure all log levels reflect the severity and actionability of the issue.</li><li>You <code>SHOULD</code> consider replacing repetitive logs with metrics when appropriate. You <code>SHOULD</code> prefer metrics for tracking recurring behavior or performance patterns instead of relying on log statements.</li><li>You <code>MUST</code> use <code>info</code> or <code>debug</code> levels for logs that are purely observational and don’t require intervention.</li></ul><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h2><h3 id="error-reporter" tabindex="-1">Error Reporter <a class="header-anchor" href="#error-reporter" aria-label="Permalink to &quot;Error Reporter&quot;">​</a></h3><p>An Error Reporter would be a service like <a href="https://sentry.io/" target="_blank" rel="noreferrer">Sentry</a>, <a href="https://www.datadoghq.com/product/error-tracking/" target="_blank" rel="noreferrer">Datadog Error Tracking</a>.</p>',16)])])}const p=r(i,[["render",l]]);export{h as __pageData,p as default};
